def save_image_bytes(image, output: Path) -> bytes:

    ext = output.suffix.lower()
    buf = io.BytesIO()
    if ext in (".jpg", ".jpeg", ".jpe", ".jfif"):
        image = image.convert("RGB")
        image.save(buf, format="JPEG", quality=95)
    else:
        image.save(buf, format="PNG")
    return buf.getvalue()
